@@ -0,0 +1,29 @@
+import { AppError } from "../errors.js";
+
+const cookPaths = [
+  /^\/recipes\/[^/]+\/cook$/,
+  /^\/batches\/[^/]+\/waste$/,
+  /^\/temperatures$/,
+  /^\/stocktakes\/[^/]+\/counts$/,
+];
+
+/** Authenticates a bearer key and checks its role for the requested operation. */
+export function authorize(store, authorization, method, path) {
+  const token = typeof authorization === "string" ? /^Bearer ([^\s]+)$/i.exec(authorization)?.[1] : null;
+  const identity = token ? store.data.apiKeys.find((entry) => entry.key === token) : null;
+  if (!identity) throw new AppError("unauthorized");
+  if (identity.role === "manager") return identity;
+  if (["viewer", "cook"].includes(identity.role) && method === "GET" && path !== "/audit") return identity;
+  if (identity.role === "cook" && method === "POST" && cookPaths.some((pattern) => pattern.test(path))) return identity;
+  throw new AppError("forbidden");
+}
+
+/** Appends the audit record for a successful write request. */
+export function recordAudit(store, entry) {
+  store.data.audit.push(entry);
+}
+
+/** Lists audit entries newest first, including requests with the same time. */
+export function listAudit(store) {
+  return structuredClone(store.data.audit).reverse().sort((a, b) => b.time.localeCompare(a.time));
+}
